package tv.casa.launcher;

import android.app.*;
import android.content.*;
import android.content.pm.*;
import android.hardware.input.InputManager;
import android.media.tv.*;
import android.os.*;
import android.provider.Settings;
import android.view.*;
import android.widget.*;
import java.text.DateFormat;
import java.util.*;
import java.util.concurrent.*;

/** On-demand game hub. Only Android's input and TV-input callbacks run while visible. */
public final class GameModeActivity extends GameUi implements InputManager.InputDeviceListener {
    private GameStore store;private TvInputManager tv;private InputManager input;
    private final Handler handler=new Handler();private final TextView[] hdmi=new TextView[3];
    private final TvInputInfo[] sources=new TvInputInfo[3];private TextView controllers;private LinearLayout apps,web;
    private ExecutorService worker;private boolean alive=true;
    private final TvInputManager.TvInputCallback tvEvents=new TvInputManager.TvInputCallback(){public void onInputStateChanged(String id,int state){refreshHdmi();}public void onInputAdded(String id){refreshHdmi();}public void onInputRemoved(String id){refreshHdmi();}public void onInputUpdated(String id){refreshHdmi();}};
    public void onCreate(Bundle saved){super.onCreate(saved);scale=getResources().getDisplayMetrics().widthPixels/960f;fullscreen();store=new GameStore(this);worker=Executors.newSingleThreadExecutor();tv=(TvInputManager)getSystemService(TV_INPUT_SERVICE);input=(InputManager)getSystemService(INPUT_SERVICE);
        ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setBackgroundColor(0xFF000000);
        LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setClipChildren(false);box.setClipToPadding(false);box.setPadding(px(38),px(24),px(38),px(30));box.setBackground(new android.graphics.drawable.GradientDrawable(android.graphics.drawable.GradientDrawable.Orientation.TL_BR,new int[]{0xB5171B22,0xD9171B22,0xF0171B22}));scroll.addView(box);
        LinearLayout head=new LinearLayout(this);head.setGravity(Gravity.CENTER_VERTICAL);TextView brand=text("VELIRA TV  /  JUEGOS",12,AuraTheme.ACCENT);head.addView(brand,new LinearLayout.LayoutParams(0,px(36),1));TextView close=button("Volver a Casa",this::finish);head.addView(close,new LinearLayout.LayoutParams(px(160),px(38)));box.addView(head);
        TextView title=text("Todo listo para jugar.",36,AuraTheme.INK);title.setTypeface(android.graphics.Typeface.create("sans-serif-light",0));box.addView(title,new LinearLayout.LayoutParams(-1,px(51)));
        TextView intro=text("Tus entradas, mandos y juegos en un solo lugar.",14,AuraTheme.MUTED);box.addView(intro,new LinearLayout.LayoutParams(-1,px(25)));
        section(box,"Entradas HDMI");LinearLayout row=new LinearLayout(this);row.setClipChildren(false);
        for(int i=0;i<3;i++){final int port=i+1;TextView b=button("HDMI "+port,()->launchHdmi(port));b.setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);b.setMaxLines(4);b.setTextSize(android.util.TypedValue.COMPLEX_UNIT_PX,px(13));b.setOnLongClickListener(v->{rename(port);return true;});wireHdmiKeys(b,port);hdmi[i]=b;LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,px(88),1);if(i>0)p.leftMargin=px(12);row.addView(b,p);}box.addView(row);
        TextView tip=text("Mantén OK para cambiar el nombre. C645: HDMI 1 para laptop · hasta 4K/60 Hz · ARC/eARC comparte HDMI 3.",11,AuraTheme.MUTED);box.addView(tip,new LinearLayout.LayoutParams(-1,px(32)));
        LinearLayout tools=new LinearLayout(this);TextView pairing=button("Conectar mando\nBusca y vincula un mando en Android  ›",this::pairController);tools.addView(pairing,new LinearLayout.LayoutParams(0,px(70),1));TextView gamebar=button("Panel de juego TCL\nAjustes y herramientas de juego  ›",()->open(new Intent("com.tcl.gamebar.main").setPackage("com.tcl.gamebar")));LinearLayout.LayoutParams gp=new LinearLayout.LayoutParams(0,px(70),1);gp.leftMargin=px(12);tools.addView(gamebar,gp);box.addView(tools);
        controllers=text("",12,AuraTheme.MUTED);controllers.setPadding(0,px(8),0,px(8));
        section(box,"Juega desde Internet");TextView browserCard=button("Abrir navegador gamer\nJuega desde la nube y abre tus juegos online  ›",()->browser(GamePolicy.URLS[0]));box.addView(browserCard,new LinearLayout.LayoutParams(-1,px(70)));box.addView(controllers,new LinearLayout.LayoutParams(-1,-2));
        LinearLayout sites=new LinearLayout(this);for(int i=0;i<GamePolicy.URLS.length;i++){final int n=i;TextView b=button(GamePolicy.NAMES[i],()->browser(GamePolicy.URLS[n]));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,px(54),1);if(i>0)p.leftMargin=px(12);sites.addView(b,p);}box.addView(sites);
        TextView online=text("Algunos juegos necesitan mando o teclado. La compatibilidad depende del sitio y del WebView del TV.",11,AuraTheme.MUTED);box.addView(online,new LinearLayout.LayoutParams(-1,px(31)));
        web=new LinearLayout(this);web.setOrientation(1);box.addView(web);section(box,"Juegos y emuladores instalados");apps=new LinearLayout(this);apps.setOrientation(1);box.addView(apps);apps.addView(text("Buscando juegos…",13,AuraTheme.MUTED));
        entry(box,"Borrar favoritos e historial web",()->new AlertDialog.Builder(this).setTitle("¿Borrar los accesos guardados?").setMessage("Se borrarán solo los favoritos e historial del navegador de Casa.").setPositiveButton("Borrar",(d,w)->{store.clear();refreshWeb();}).setNegativeButton("Cancelar",null).show());
        FrameLayout scene=new FrameLayout(this);ImageView landscape=new ImageView(this);landscape.setScaleType(ImageView.ScaleType.CENTER_CROP);worker.execute(()->{android.graphics.Bitmap bitmap=Assets.landscape(getApplicationContext());runOnUiThread(()->{if(alive)landscape.setImageBitmap(bitmap);});});scene.addView(landscape,new FrameLayout.LayoutParams(-1,-1));scroll.setBackgroundColor(android.graphics.Color.TRANSPARENT);scene.addView(scroll,new FrameLayout.LayoutParams(-1,-1));setContentView(scene);hdmi[0].requestFocus();scanApps();
    }
    private void wireHdmiKeys(TextView view,int port){final boolean[] held={false};final Runnable rename=()->{if(view.hasFocus()&&hasWindowFocus()){held[0]=true;rename(port);}};view.setOnKeyListener((v,key,event)->{if(key!=KeyEvent.KEYCODE_DPAD_CENTER&&key!=KeyEvent.KEYCODE_ENTER&&key!=KeyEvent.KEYCODE_NUMPAD_ENTER&&key!=KeyEvent.KEYCODE_BUTTON_A)return false;if(event.getAction()==KeyEvent.ACTION_DOWN){if(event.getRepeatCount()==0){held[0]=false;handler.postDelayed(rename,600);}else if(!held[0]){handler.removeCallbacks(rename);held[0]=true;rename(port);}return true;}if(event.getAction()==KeyEvent.ACTION_UP){handler.removeCallbacks(rename);if(!held[0]&&!event.isCanceled())launchHdmi(port);return true;}return true;});}
    private void pairController(){for(Intent intent:new Intent[]{new Intent("com.android.tv.settings.ACCESSORIES_CONNECTED_DEVICES").setPackage("com.android.tv.settings"),new Intent(Settings.ACTION_BLUETOOTH_SETTINGS),new Intent(Settings.ACTION_SETTINGS)})try{startActivity(intent);return;}catch(Exception ignored){}Toast.makeText(this,"Abre los accesorios desde los ajustes del TV",0).show();}
    private void refreshHdmi(){Arrays.fill(sources,null);try{if(tv!=null)for(TvInputInfo info:tv.getTvInputList()){if(info.getType()!=TvInputInfo.TYPE_HDMI)continue;String label=String.valueOf(info.loadLabel(this)).replaceAll("\\s","").toUpperCase(Locale.ROOT);for(int i=0;i<3;i++)if(label.matches(".*HDMI"+(i+1)+"(?:[^0-9].*)?"))sources[i]=info;}}catch(Exception ignored){}
        for(int i=0;i<3;i++){String state="Estado no disponible";try{if(sources[i]!=null){int s=tv.getInputState(sources[i].getId());state=s==TvInputManager.INPUT_STATE_CONNECTED?"Conectada":s==TvInputManager.INPUT_STATE_CONNECTED_STANDBY?"En espera":"Sin señal / desconectada";}}catch(Exception ignored){}long last=store.last("hdmi-last-"+(i+1));hdmi[i].setText((i==2&&store.alias(i+1).equals("HDMI 3")?"HDMI 3 · ARC/eARC":store.alias(i+1))+"\nHDMI "+(i+1)+" · "+state+"\n"+(last==0?"Aún sin abrir desde Casa":"Casa · "+date(last)));}
    }
    private String date(long time){return DateFormat.getDateTimeInstance(DateFormat.SHORT,DateFormat.SHORT).format(new Date(time));}
    private void launchHdmi(int port){TvInputInfo source=sources[port-1];if(source==null){Toast.makeText(this,"Entrada no identificada; abre las entradas originales del TV",0).show();Intent i=getPackageManager().getLeanbackLaunchIntentForPackage("com.tcl.tv");if(i!=null)open(i);return;}try{startActivity(new Intent(Intent.ACTION_VIEW,TvContract.buildChannelUriForPassthroughInput(source.getId())).setPackage("com.tcl.tv"));store.used("hdmi-last-"+port);}catch(Exception e){Toast.makeText(this,"No se pudo abrir esta entrada",0).show();}}
    private void rename(int port){EditText edit=new EditText(this);edit.setSingleLine(true);edit.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(40)});edit.setText(store.alias(port));new AlertDialog.Builder(this).setTitle("Nombre de HDMI "+port).setView(edit).setPositiveButton("Guardar",(d,w)->{store.alias(port,edit.getText().toString());refreshHdmi();}).setNeutralButton("Restablecer",(d,w)->{store.alias(port,"");refreshHdmi();}).setNegativeButton("Cancelar",null).show();}
    private void browser(String url){open(new Intent(this,GameBrowserActivity.class).putExtra("url",url));}
    private void refreshWeb(){web.removeAllViews();for(String key:new String[]{"favorites","recent"}){ArrayList<GameStore.Page> pages=store.pages(key);if(pages.isEmpty())continue;section(web,key.equals("favorites")?"Favoritos web":"Últimas páginas abiertas");for(GameStore.Page page:pages)entry(web,page.title,()->browser(page.url));}}
    private void scanApps(){worker.execute(()->{TreeMap<String,String> found=new TreeMap<>(String.CASE_INSENSITIVE_ORDER);HashSet<String> seen=new HashSet<>();PackageManager pm=getPackageManager();try{for(String cat:new String[]{Intent.CATEGORY_LEANBACK_LAUNCHER,Intent.CATEGORY_LAUNCHER})for(ResolveInfo r:pm.queryIntentActivities(new Intent(Intent.ACTION_MAIN).addCategory(cat),0)){ApplicationInfo a=r.activityInfo.applicationInfo;String p=a.packageName;if(!seen.add(p))continue;boolean game=a.category==ApplicationInfo.CATEGORY_GAME||(a.flags&ApplicationInfo.FLAG_IS_GAME)!=0||p.equals("com.nvidia.geforcenow")||p.equals("com.google.android.play.games")||p.startsWith("com.retroarch")||p.equals("org.ppsspp.ppsspp")||p.equals("org.dolphinemu.dolphinemu")||p.startsWith("com.explusalpha.");if(game)found.put(pm.getApplicationLabel(a).toString()+"\u0000"+p,p);}}catch(Exception ignored){}
            runOnUiThread(()->{if(!alive)return;apps.removeAllViews();if(found.isEmpty())apps.addView(text("No se detectaron juegos. Las demás apps siguen en la biblioteca de Casa.",13,AuraTheme.MUTED));for(Map.Entry<String,String> e:found.entrySet())entry(apps,e.getKey().split("\u0000")[0],()->{Intent i=pm.getLeanbackLaunchIntentForPackage(e.getValue());if(i==null)i=pm.getLaunchIntentForPackage(e.getValue());if(i!=null)open(i);});});});}
    private void refreshControllers(){StringBuilder lines=new StringBuilder();try{for(int id:InputDevice.getDeviceIds()){InputDevice d=InputDevice.getDevice(id);if(!isGamepad(d))continue;String key="pad-"+Integer.toHexString(d.getDescriptor().hashCode());long last=store.last(key);if(last==0){store.used(key);last=store.last(key);}if(lines.length()>0)lines.append('\n');lines.append(d.getName()).append(" · conectado · ").append(d.isExternal()?"externo":"integrado").append("\nBatería: ").append(battery(d)).append(" · última detección en Casa: ").append(date(last));}}catch(Exception ignored){}
        if(lines.length()==0)lines.append("Sin mando de juego detectado. Usa Conectar mando para buscar y vincular en Android.");lines.append("\nLa búsqueda y reconexión Bluetooth las gestiona el televisor.");controllers.setText(lines.toString());}
    private boolean isGamepad(InputDevice d){if(d==null||d.isVirtual()||!d.isExternal())return false;String name=d.getName().toLowerCase(Locale.ROOT);if(name.startsWith("tcl_rc")||name.contains("remote")||name.contains("virtual"))return false;boolean axes=d.getMotionRange(MotionEvent.AXIS_X,InputDevice.SOURCE_JOYSTICK)!=null&&d.getMotionRange(MotionEvent.AXIS_Y,InputDevice.SOURCE_JOYSTICK)!=null;boolean[] keys=d.hasKeys(KeyEvent.KEYCODE_BUTTON_A,KeyEvent.KEYCODE_BUTTON_B,KeyEvent.KEYCODE_BUTTON_X,KeyEvent.KEYCODE_BUTTON_Y);return axes||(d.supportsSource(InputDevice.SOURCE_GAMEPAD)&&keys[0]&&keys[1]&&keys[2]&&keys[3]);}
    private String battery(InputDevice device){if(Build.VERSION.SDK_INT>=31){try{android.hardware.BatteryState b=device.getBatteryState();float n=b.getCapacity();if(b.isPresent()&&n>=0&&n<=1)return Math.round(n*100)+" %";}catch(Exception ignored){}}return "no disponible";}
    public void onInputDeviceAdded(int id){InputDevice d=InputDevice.getDevice(id);if(isGamepad(d))store.used("pad-"+Integer.toHexString(d.getDescriptor().hashCode()));refreshControllers();}
    public void onInputDeviceRemoved(int id){refreshControllers();}public void onInputDeviceChanged(int id){refreshControllers();}
    public void onResume(){super.onResume();fullscreen();if(tv!=null)tv.registerCallback(tvEvents,handler);if(input!=null)input.registerInputDeviceListener(this,handler);refreshHdmi();refreshControllers();refreshWeb();}
    public void onPause(){if(tv!=null)tv.unregisterCallback(tvEvents);if(input!=null)input.unregisterInputDeviceListener(this);handler.removeCallbacksAndMessages(null);super.onPause();}
    public void onDestroy(){alive=false;worker.shutdownNow();handler.removeCallbacksAndMessages(null);super.onDestroy();}
}
